 public static partial class SelfTests {
  static string ReceivedKey(int number=9){string raw=Key(number).Substring(0,6)+"12345678000195"+Key(number).Substring(20,23);int sum=0,w=2;for(int i=42;i>=0;i--){sum+=(raw[i]-48)*w;w=w==9?2:w+1;}int dv=11-sum%11;return raw+(dv>=10?0:dv).ToString();}
  static byte[] ReceivedSummary(int number=9,string status="1"){var x=Rules.Xml(Summary());XNamespace n=Rules.NfeNs;x.Root.Element(n+"chNFe").Value=ReceivedKey(number);x.Root.Element(n+"cSitNFe").Value=status;return Rules.Utf8(x);}
  static byte[] ReceivedInvoice(int number=9){var x=Rules.Xml(Invoice(false,number));XNamespace n=Rules.NfeNs;x.Root.Element(n+"NFe").Element(n+"infNFe").SetAttributeValue("Id","NFe"+ReceivedKey(number));x.Root.Element(n+"protNFe").Element(n+"infProt").Element(n+"chNFe").Value=ReceivedKey(number);return Rules.Utf8(x);}
  static byte[] ScienceReply(string key,string code="135",int env=1,string type="210210",string recipient=SampleCnpj){XNamespace n=Rules.NfeNs,s="http://www.w3.org/2003/05/soap-envelope";return Rules.Utf8(new XDocument(new XElement(s+"Envelope",new XElement(s+"Body",new XElement(n+"retEnvEvento",new XElement(n+"tpAmb",env),new XElement(n+"cStat","128"),new XElement(n+"retEvento",new XElement(n+"infEvento",new XElement(n+"tpAmb",env),new XElement(n+"cStat",code),new XElement(n+"xMotivo","Resposta de teste"),new XElement(n+"chNFe",key),new XElement(n+"tpEvento",type),new XElement(n+"nSeqEvento","1"),new XElement(n+"CNPJDest",recipient),new XElement(n+"nProt","123456789012345"))))))));}
  sealed class ScienceFake:ISefaz {
   public Queue<byte[]> Events=new Queue<byte[]>(),Docs=new Queue<byte[]>();public int Sent,Queries;
   public byte[] Science(string c,int e,string k,CancellationToken t){t.ThrowIfCancellationRequested();Sent++;if(Events.Count==0)throw new IOException("Resposta perdida após envio");return Events.Dequeue();}
   public byte[] Distribute(string c,int u,int e,string ns,string k,CancellationToken t){t.ThrowIfCancellationRequested();Queries++;return Docs.Dequeue();}
  }
