   fake.Events.Enqueue(ScienceReply(key));Check(runner.Run(35,CancellationToken.None)==1&&fake.Sent==1,"envia ciência após ativação");var registered=ss.Load(SampleCnpj,1).Records.Single();Check(registered.Registered&&registered.Code=="135"&&registered.Protocol!=""&&registered.Queued,"registra protocolo e marca chave enfileirada");Check(File.ReadAllBytes(registered.ResponsePath).SequenceEqual(ScienceReply(key)),"preserva retorno original da manifestação");var q=queues.Load(SampleCnpj,1);Check(q.AutoContinue&&q.Pending==1&&q.Jobs.Single().AwaitXml&&q.Next>DateTime.UtcNow.AddMinutes(59),"agenda XML após uma hora sem consultar imediatamente");Check(runner.Run(35,CancellationToken.None)==0&&fake.Sent==1,"não repete ciência já enviada");new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);Check(fake.Queries==0,"fila espera liberação do XML antes de consultar");
