   q.Jobs.Single(j=>j.Key==key).NotBefore=DateTime.UtcNow.AddMinutes(-1);queues.Save(SampleCnpj,1,q);fake.Docs.Enqueue(Response("138","1","1",ReceivedInvoice()));new KeyBatchRunner(states,queues,lib,fake,null).Run(CancellationToken.None);Check(queues.Load(SampleCnpj,1).Jobs.Single(j=>j.Key==key).Status=="Baixada"&&lib.List().Any(d=>d.Key==key&&d.Category=="Recebidas"),"XML liberado é salvo em Recebidas e conclui a chave");new AutoScienceRunner(states,ss,queues,lib,fake,null).Run(35,CancellationToken.None);Check(fake.Sent==1,"reabrir e baixar XML não repete ciência");
