   var failLib=new XmlLibrary(Path.Combine(root,"science-failed-lib"),SampleCnpj,1);failLib.Store(ReceivedSummary(20),"1");var failLedger=new ScienceStore(Path.Combine(root,"science-failed-ledger"));failLedger.Enable(SampleCnpj,1,true);var failFake=new ScienceFake();var failRunner=new AutoScienceRunner(states,failLedger,queues,failLib,failFake,null);Reject(()=>failRunner.Run(35,CancellationToken.None),"rede incerta preserva tentativa antes do envio");Check(!failLedger.Load(SampleCnpj,1).Enabled&&failLedger.Load(SampleCnpj,1).Records.Single().Status=="Incerta","envio incerto desliga ciência automática");failLedger.Enable(SampleCnpj,1,true);failRunner.Run(35,CancellationToken.None);Check(failFake.Sent==1,"reativar não reenvia tentativa incerta");Reject(()=>failRunner.Manual(failLib.List().Single(),35,CancellationToken.None),"envio manual compartilha proteção de duplicidade");
