   var capQueues=new KeyQueueStore(Path.Combine(root,"science-cap-q"));var capQueue=new KeyQueue{Uf=35,AutoContinue=true};capQueue.Add(new[]{ReceivedKey(40)});capQueue.Jobs[0].AwaitXml=true;capQueue.Jobs[0].XmlChecks=23;capQueues.Save(SampleCnpj,1,capQueue);var capFake=new ScienceFake();capFake.Docs.Enqueue(Response("137","0","0"));new KeyBatchRunner(states,capQueues,lib,capFake,null).Run(CancellationToken.None);Check(capQueues.Load(SampleCnpj,1).Jobs[0].Status=="XML indisponível"&&capQueues.Load(SampleCnpj,1).Pending==0,"24 retornos sem XML encerram repetição para revisão");
