  static void TestScience596(string root){var lib=new XmlLibrary(Path.Combine(root,"596-lib"),SampleCnpj,1);lib.Store(ReceivedSummary(150),"1");lib.Store(ReceivedSummary(151),"2");var docs=lib.List();string rejected=docs[0].Key;var states=new StateStore(Path.Combine(root,"596-states"));var store=new ScienceStore(Path.Combine(root,"596-ledger"));store.Enable(SampleCnpj,1,true);var queues=new KeyQueueStore(Path.Combine(root,"596-queue"));var client=new ScienceFake();client.Events.Enqueue(ScienceReply(rejected,"596"));client.Events.Enqueue(ScienceReply(docs[1].Key));var runner=new AutoScienceRunner(states,store,queues,lib,client,null);Check(runner.Run(35,CancellationToken.None)==2&&client.Sent==2&&store.Load(SampleCnpj,1).Enabled,"596 não interrompe ciência das demais notas");var record=store.Load(SampleCnpj,1).Records.Single(r=>r.Key==rejected);Check(!record.Registered&&record.Status=="Rejeitada"&&record.Queued,"596 permanece rejeitado e consulta XML sem assumir ciência registrada");var job=queues.Load(SampleCnpj,1).Jobs.Single(j=>j.Key==rejected);Check(job.ScienceCode=="596"&&!job.AwaitXml&&job.NotBefore<=DateTime.UtcNow,"consulta de verificação após 596 não aguarda nova ciência");var manual=runner.Manual(docs[0],35,CancellationToken.None);Check(manual.Code=="596"&&client.Sent==2,"repetir ação manual com 596 consulta histórico sem reenviar evento");int number=rejected==ReceivedKey(150)?150:151;client.Docs.Enqueue(Response("138","1","1",ReceivedInvoice(number)));new KeyBatchRunner(states,queues,lib,client,null).Run(CancellationToken.None);Check(queues.Load(SampleCnpj,1).Jobs.Single(j=>j.Key==rejected).Status=="Baixada"&&lib.List().Any(d=>d.Key==rejected&&d.Category=="Recebidas"),"baixa XML já liberado apesar de ciência 596 rejeitada");Check(states.Load(SampleCnpj,1).Last==Rules.Nsu("0")&&!store.Load(SampleCnpj,1).Records.Single(r=>r.Key==rejected).Registered,"download após 596 não altera NSU nem transforma rejeição em sucesso");
   var missingLib=new XmlLibrary(Path.Combine(root,"596-missing-lib"),SampleCnpj,1);var missingItem=missingLib.Store(ReceivedSummary(152),"1");var missingStore=new ScienceStore(Path.Combine(root,"596-missing-ledger"));var legacyState=new ScienceState();legacyState.Records.Add(new ScienceRecord{Key=missingItem.Key,At=DateTime.UtcNow.AddDays(-1),Code="596",Status="Rejeitada",Message="Prazo de ciência encerrado"});missingStore.Save(SampleCnpj,1,legacyState);var missingQueues=new KeyQueueStore(Path.Combine(root,"596-missing-q"));var missingClient=new ScienceFake();var missingRunner=new AutoScienceRunner(states,missingStore,missingQueues,missingLib,missingClient,null);Check(missingRunner.ScheduleDownloads(35,CancellationToken.None)==1&&!missingStore.Load(SampleCnpj,1).Enabled&&missingClient.Sent==0,"migra 596 da versão anterior sem ativar ciência ou enviar novo evento");Check(missingRunner.ScheduleDownloads(35,CancellationToken.None)==0,"migração do 596 é persistente e não reinsere resultados");missingClient.Docs.Enqueue(Response("138","1","1",ReceivedSummary(152)));new KeyBatchRunner(states,missingQueues,missingLib,missingClient,null).Run(CancellationToken.None);var missingJob=missingQueues.Load(SampleCnpj,1).Jobs.Single();Check(missingJob.Status=="Necessita manifestação"&&missingJob.Message.Contains("sem registro de ciência aceito"),"retorno somente de resumo após 596 informa manifestação pendente");new KeyBatchRunner(states,missingQueues,missingLib,missingClient,null).Run(CancellationToken.None);Check(missingClient.Queries==1&&missingClient.Sent==0&&missingQueues.Load(SampleCnpj,1).Pending==0,"não repete consultas de resumo nem ciência rejeitada automaticamente");
   var absentQueues=new KeyQueueStore(Path.Combine(root,"596-absent-q"));var absent=new KeyQueue{Uf=35,AutoContinue=true};absent.Add(new[]{ReceivedKey(153)});absent.Jobs[0].ScienceCode="596";absentQueues.Save(SampleCnpj,1,absent);var absentClient=new ScienceFake();absentClient.Docs.Enqueue(Response("137","0","0"));new KeyBatchRunner(states,absentQueues,missingLib,absentClient,null).Run(CancellationToken.None);Check(absentQueues.Load(SampleCnpj,1).Jobs.Single().Status=="Não encontrada"&&absentQueues.Load(SampleCnpj,1).Jobs.Single().Message.Contains("não registra ciência"),"137 após 596 não promete XML ou manifestação aceita");
   var blockedStates=new StateStore(Path.Combine(root,"596-block-state"));var cursor=new CursorState();cursor.KeyQueries=Enumerable.Range(0,20).Select(i=>DateTime.UtcNow.AddMinutes(-1)).ToList();blockedStates.Save(SampleCnpj,1,cursor);var blockedQueues=new KeyQueueStore(Path.Combine(root,"596-block-q"));blockedQueues.Save(SampleCnpj,1,absent);var blockedClient=new ScienceFake();new KeyBatchRunner(blockedStates,blockedQueues,missingLib,blockedClient,null).Run(CancellationToken.None);Check(blockedClient.Queries==0&&blockedQueues.Load(SampleCnpj,1).Pending==1&&blockedQueues.Load(SampleCnpj,1).Next>DateTime.UtcNow.AddMinutes(58),"download de verificação 596 respeita limite de vinte chaves por hora");
